head.script:
// [분리 사유]
//  _1 : 단일 Line 그리드에서의 인덱스 기반 설정(숨겨진 Column 포함 인덱스 / inputType 허용 목록 / Column 단위 적용 등)
//  _3 (본 샘플) : Body 를 MultiLine(2줄) 로 구성해야만 검증 가능한 @param columnInfo 의
//                "Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다." 문구 전용.
//                그리드 구성 자체(gBody 에 <w2:row> 2개)가 _1 과 달라 별도 샘플로 분리한다.

// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setMaxLength]<br/>Body Column 정보를 사용하여 특정 Column 의 maxLength 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine(한 Row 가 여러 줄로 표시)이어도 모든 Column 은 고유의 인덱스값을 가지며, columnInfo 인덱스로 해당 Column 의 maxLength 속성을 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = name(고유 인덱스 0) / birth(고유 인덱스 1)
//  - 2줄 = memo(고유 인덱스 2) / etc(고유 인덱스 3)
//  - Row 가 MultiLine 이어도 name~etc 는 좌상단 -> 우하단 순의 고유 인덱스(0~3) 를 가짐
//  - 4개 Column 모두 inputType="text" 이고 maxLength 는 초기 미설정 -> setMaxLength 적용 대상 Column 만 값이 바뀌는지 확인 가능
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 name(고유 인덱스 0)/birth(1), 2줄 memo(2)/etc(3). 4개 Column 모두 inputType=text, maxLength 초기 미설정.\n[절차] columnInfo(고유 인덱스) 와 maxLength 를 선택한 뒤 (setMaxLength 실행) 클릭 -> 이어서 해당 Column 의 셀을 더블클릭해 값을 입력하고 포커스를 빼면(다른 셀 클릭 또는 Enter) onafteredit 로 입력값과 길이가 결과창에 출력됨.\n[확인] 출력된 전체 Column maxLength 매핑에서 선택한 고유 인덱스의 Column 하나만 값이 바뀌는지 확인. MultiLine 이어도 2줄에 배치된 memo(2)/etc(3) 가 고유 인덱스로 정확히 지목됨. 편집 후 출력되는 입력값 길이로 지정한 Column 에만 최대 길이가 적용됐는지 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (MultiLine 2줄 : name/birth(1줄), memo/etc(2줄))
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="birth" name="birth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="etc" name="etc" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "HONG", "birth": "19850315", "memo": "메모0", "etc": "비고0" },
        { "name": "KIM",  "birth": "19900720", "memo": "메모1", "etc": "비고1" },
        { "name": "LEE",  "birth": "19880103", "memo": "메모2", "etc": "비고2" }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" ev:onafteredit="scwin.target1_onafteredit" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setMaxLength MultiLine 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="이름(1줄, 고유 인덱스 0)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="생년월일(1줄, 1)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="memo(2줄, 고유 인덱스 2)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="비고(2줄, 3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // 고유 인덱스 0 : name (text, maxLength 미설정, 1줄)
    strTarget += '<w2:column width="280" inputType="text" editType="text" id="name" dataList="name"></w2:column>';
    // 고유 인덱스 1 : birth (text, maxLength 미설정, 1줄)
    strTarget += '<w2:column width="*" inputType="text" editType="text" id="birth" dataList="birth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // 고유 인덱스 2 : memo (text, maxLength 미설정, 2줄) -> MultiLine 고유 인덱스 2
    strTarget += '<w2:column width="280" inputType="text" editType="text" id="memo" dataList="memo"></w2:column>';
    // 고유 인덱스 3 : etc (text, maxLength 미설정, 2줄)
    strTarget += '<w2:column width="*" inputType="text" editType="text" id="etc" dataList="etc"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// setMaxLength 실행 : par_columnInfo(MultiLine 상의 고유 인덱스) 로 호출
//  - MultiLine(2줄) 이어도 각 Column 은 고유 인덱스로 지목되어 해당 Column 에만 maxLength 가 설정됨
scwin.btn_setMaxLength_onclick = function () {
    // columnInfo 는 MultiLine 상의 고유 컬럼 인덱스(Number) 로 전달
    let colIndex = Number(par_columnInfo.getValue());
    let maxLength = par_maxLength.getValue();

    target1.setMaxLength(colIndex, maxLength);

    // 설정 결과 확인 : 전체 Column 의 maxLength 를 조회하여 선택한 고유 인덱스의 Column 만 변경됐는지 확인
    let all = [];
    for (let i = 0; i < 4; i++) {
        all.push(i + "(" + target1.getColumnID(i) + ")=" + target1.getMaxLength(i));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setMaxLength(" + colIndex + ", " + maxLength + ") 실행 -> 전체 Column maxLength [고유 인덱스(ID)=값] " + all.join(" / "));
}



// 셀 편집모드가 종료되어 포커스가 빠질 때 발생 : 실제 저장된 셀 데이터와 길이를 출력
//  - MultiLine 이므로 같은 rowIndex 라도 columnIndex(0~3) 고유 인덱스로 위/아래 줄의 Column 이 구분된다.
//  - 값은 getCellData 로 실제 저장 데이터 기준으로 읽는다.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let colID = target1.getColumnID(columnIndex);
    let saved = target1.getCellData(rowIndex, colID);
    saved = (saved === null || saved === undefined) ? "" : String(saved);

    wf_body_bottom.getObj("scwin").setReturnValue("onafteredit -> Row " + rowIndex + " / Column 인덱스 " + columnIndex + "(" + colID + ") -> 입력값 : " + saved + " (길이 " + saved.length + ")");
}
